",\n    \"turndown-plugin-gfm\": \"^1.0.2\",\n    \"zustand\": \"^5.0.12\"\n  },\n  \"devDependencies\": {\n    \"@types/express\": \"^5.0.6\",\n    \"@types/multer\": \"^2.1.0\",\n    \"@types/node\": \"^25.5.0\",\n    \"@types/react\": \"^19.2.14\",\n    \"@types/react-dom\": \"^19.2.3\",\n    \"@vitejs/plugin-react\": \"^5.0.0\",\n    \"tsx\": \"^4.21.0\",\n    \"typescript\": \"^6.0.2\",\n    \"vite\": \"^7.1.2\"\n  }\n}\n"
