= performance.now();\n      timings[name] = Math.round(now - stageStartedAt);\n      stageStartedAt = now;\n    };\n\n    try {\n      const configuration = await notesDataStore.getWechatConfiguration(user.id);\n\n      if (!configuration) {\n        response.status(409).json({\n          error: \"请先在设置中配置并连通当前账号的公众号 AppID 和 AppSecret。\",\n        });\n        return;\n      }\n\n      const body = request.body || {};\n      const theme = resolveTheme(body);\n      const markdown = await resolveMarkdown(body);\n      const publicBaseUrl = getPublicBaseUrl(request);\n      const prepared = prepareWechatDraftArticle(\n        markdown,\n        resolveFooterConfig(body),\n        theme,\n      );\n      assertWechatDraftContentLimits(prepared.html);\n      recordStage(\"prepare\");\n      const accessToken = await getWechatAccessToken(configuration);\n      recordStage(\"token\");\n      const content = await replaceDraftContentImages(\n        prepared.html,\n        accessToken,\n        publicBaseUrl,\n        prepared.sourceByPlaceholder,\n        collectMarkdownImageSources(markdown)[0],\n      );\n      assertWechatDraftContentLimits(content.html);\n      recordStage(\"images\");\n      const thumbMediaId = await uploadDraftCover(\n        markdown,\n        accessToken,\n        publicBaseUrl,\n        theme,\n        content.permanentImagesBySource,\n        content.coverImage,\n      );\n      recordStage(\"cover\");\n      const title = getWechatDraftTitle(markdown);\n      const mediaId = await addWechatDraft(accessToken, {\n        content: content.html,\n        thumbMediaId,\n        title,\n      });\n      recordStage(\"save\");\n      response.setHeader(\n        \"Server-Timing\",\n        Object.entries({\n          ...timings,\n          total: Math.round(performance.now() - startedAt),\n        }).map(([name, duration]) => `${name};dur=${duration}`).join(\", \"),\n      );\n\n      response.json({\n        imageCount: content.imageCount,\n        mediaId,\n        theme,\n        title,\n      });\n    } catch (error) {\n      console.error(\"Wechat draft publication failed:\", error);\n\n      const status =\n        error instanceof UnsupportedExportThemeError ||\n        error instanceof WechatDraftPreparationError\n          ? 400\n          : error instanceof QiniuConfigurationError\n            ? 503\n            : error instanceof QiniuUploadError ||\n                error instanceof WechatOfficialApiError\n              ? 502\n              : 500;\n\n      response.status(status).json({\n        error:\n          error instanceof Error ? error.message : \"发布公众号草稿失败。\",\n      });\n    } finally {\n      console.info(\"Wechat draft timing:\", JSON.stringify({\n        status: response.statusCode,\n        ...timings,\n        total: Math.round(performance.now() - startedAt),\n      }));\n    }\n  },\n);\n\napp.get(\"/api/health\", (_request: Request, response: Response) => {\n  response.json({ ok: true });\n});\n\nconst wechatImportLimiter = new WechatImportRateLimiter();\nconst fetchWechatPage = createWechatPageFetcher({\n  getBrowser: async () => (await getBrowser()) as WechatBrowser,\n});\nconst downloadWechatImage = createWechatImageDownloader();\n\nasync function persistImportedWechatImage(\n  request: Request,\n  image: { buffer: Buffer; contentType: string | null },\n): Promise<{ path: string; reused: boolean }> {\n  // 预览阶段写入的图片按内容哈希去重。取消创建便签时不删除文件，避免误删其他便签正在使用的同一张图。\n  const extension = detectImageFormat(image.buffer, image.contentType, null);\n\n  if (!extension || extension === \"svg\") {\n    throw new Error(\"unsupported wechat image\");\n  }\n\n  const hash = createHash(\"sha256\").update(image.buffer).digest(\"hex\");\n  const filename = `${hash}.${extension}`;\n  let reused = false;\n\n  try {\n    await fs.access(path.join(imagesDir, filename));\n    reused = true;\n  } catch {\n    reused = false;\n  }\n\n  const stored = await persistImage(request, {\n    buffer: image.buffer,\n    mimeType: image.contentType,\n    filename,\n  });\n\n  return {\n    path: stored.path,\n    reused,\n  };\n}\n\napp.post(\n  \"/api/import/wechat/preview\",\n  createWechatImportPreviewHandler({\n    isEnabled: isWechatImportEnabled,\n    limiter: wechatImportLimiter,\n    getRateIdentity: async (request) => {\n      const user = await getWorkspaceUser(request);\n      return user\n        ? { key: `user:${user.id}`, kind: \"authenticated\" }\n        : { key: `anon:${request.ip || \"unknown\"}`, kind: \"anonymous\" };\n    },\n    preview: (url, request) =>\n      previewWechatArticle(url, {\n        fetchPage: fetchWechatPage,\n        downloadImage: downloadWechatImage,\n        persistImage: (image) => persistImportedWechatImage(request, image),\n      }),\n  }),\n);\n\napp.post(\n  \"/api/images/import\",\n  async (\n    request: Request<Record<string, never>, unknown, ImageImportRequestBody>,\n    response: Response,\n  ) => {\n    try {\n      await runImageUpload(request, response);\n\n      const uploadedFile = request.file;\n\n      if (uploadedFile?.buffer) {\n        response.json(\n          await persistImage(request, {\n            buffer: uploadedFile.buffer,\n            mimeType: uploadedFile.mimetype,\n            filename: uploadedFile.originalname,\n          }),\n        );\n        return;\n      }\n\n      const sourceUrl = resolveSourceUrl(request.body?.sourceUrl);\n\n      if (!sourceUrl) {\n        response.status(400).json({\n          error: \"请拖入图片文件，或粘贴一个可访问的图片 URL。\",\n        });\n        return;\n      }\n\n      const downloadedImage = await downloadImageFromUrl(sourceUrl);\n      response.json(await persistImage(request, downloadedImage));\n    } catch (error) {\n      if (error instanceof MulterError && error.code === \"LIMIT_FILE_SIZE\") {\n        response.status(413).json({\n          error: `图片过大，单张图片不能超过 ${Math.floor(maxImageSizeBytes / 1024 / 1024)}MB。`,\n        });\n        return;\n      }\n\n      const message = error instanceof Error ? error.message : \"图片导入失败\";\n\n      console.error(\"Image import failed:\", error);\n\n      response.status(400).json({\n        error: message,\n      });\n    }\n  },\n);\n\nif (await hasDistIndex()) {\n  app.use(express.static(distDir));\n\n  app.get(\"/{*any}\", (_request: Request, response: Response) => {\n    response.sendFile(path.join(distDir, \"index.html\"));\n  });\n}\n\nawait checkAiAvailability();\n\nconst server = app.listen(port, () => {\n  console.log(`Backend listening on http://127.0.0.1:${port}`);\n});\n\nasync function closeBrowser(): Promise<void> {\n  if (!browserPromise) {\n    return;\n  }\n\n  const browser = await browserPromise;\n  await browser.close();\n  browserPromise = undefined;\n}\n\nasync function shutdown(exitCode: number): Promise<void> {\n  server.close(async () => {\n    await closeBrowser();\n    process.exit(exitCode);\n  });\n}\n\nprocess.on(\"SIGINT\", () => {\n  void shutdown(130);\n});\n\nprocess.on(\"SIGTERM\", () => {\n  void shutdown(0);\n});\n"
    },
    {
      "path": "server/site-publishing/route.ts",
      "content": "import type { Request, Response } from \"express\";\nimport { buildSiteEntries, validateSiteExportRequest, type SiteZipEntry } from \"./build.js\";\nimport { createSiteImageReader } from \"./assets.js\";\n\nexport function createSiteExportHandler(options: {\n  rootDirectory: string;\n  imagesDirectory: string;\n  publicDirectory: string;\n  publicOrigin: (request: Request) => string;\n  getUser: (request: Request, response: Response) => Promise<{ id: string } | null>;\n  isSameOrigin: (request: Request) => boolean;\n  createZip: (entries: SiteZipEntry[]) => Buffer;\n}) {\n  const running = new Set<string>();\n  return async (request: Request, response: Response): Promise<void> => {\n    response.setHeader(\"Cache-Control\", \"no-store\");\n    if (!options.isSameOrigin(request)) { response.status(403).json({ error: \"请从本站打开网站发布面板。\" }); return; }\n    const user = await options.getUser(request, response);\n    if (!user) return;\n    if (running.has(user.id) || running.size >= 2) { response.status(429).json({ error: \"已有网站导出正在进行，请稍后再试。\" }); return; }\n    let parsed;\n    try { parsed = validateSiteExportRequest(request.body); } catch (error) {\n      response.status(400).json({ error: error instanceof Error ? error.message : \"网站设置不正确。\" }); return;\n    }\n    running.add(user.id);\n    const controller = new AbortController();\n    const deadline = setTimeout(() => controller.abort(), 120_000);\n    const disconnect = () => { if (!response.writableFinished) controller.abort(); };\n    response.on(\"close\", disconnect);\n    try {\n      const entries = await buildSiteEntries(parsed, {\n        rootDirectory: options.rootDirectory, signal: controller.signal,\n        readImage: createSiteImageReader({ imagesDirectory: options.imagesDirectory, publicDirectory: options.publicDirectory, publicOrigin: options.publicOrigin(request) }),\n      });\n      controller.signal.throwIfAborted();\n      const buffer = options.createZip(entries);\n      response.setHeader(\"Content-Type\", \"application/zip\");\n      response.setHeader(\"Content-Disposition\", 'attachment; filename=\"notes-hugo-site.zip\"');\n      response.setHeader(\"X-Content-Type-Options\", \"nosniff\");\n      response.send(buffer);\n    } catch (error) {\n      if (response.destroyed) return;\n      response.status(controller.signal.aborted ? 504 : 422).json({ error: controller.signal.aborted ? \"网站生成超时，请减少便签或图片后重试。\" : error instanceof Error ? error.message : \"网站生成失败，请重试。\" });\n    } finally {\n      clearTimeout(deadline);\n      response.off(\"close\", disconnect);\n      running.delete(user.id);\n    }\n  };\n}\n"
    },
    {
      "path": "server/wechat-import/route.ts",
      "content": "import type { Request, Response } from \"express\";\nimport { WechatImportRateLimiter, type WechatImportRateKind } from \"./rate-limit.js\";\nimport { WechatImportError } from \"./types.js\";\nimport type { WechatPreviewResponse } from \"./types.js\";\nimport { parseWechatArticleInput } from \"./url.js\";\n\nexport function isWechatImportEnabled(\n  env: NodeJS.ProcessEnv = process.env,\n): boolean {\n  const value = env.WECHAT_IMPORT_ENABLED?.trim().toLowerCase() ?? \"\";\n  return value !== \"0\" && value !== \"false\" && value !== \"off\" && value !== \"no\";\n}\n\nexport interface WechatImportRateIdentity {\n  key: string;\n  kind: WechatImportRateKind;\n}\n\nexport function createWechatImportPreviewHandler(options: {\n  isEnabled?: () => boolean;\n  limiter: WechatImportRateLimiter;\n  getRateIdentity: (request: Request) => Promise<WechatImportRateIdentity>;\n  preview: (url: string, request: Request) => Promise<WechatPreviewResponse>;\n}): (request: Request, response: Response) => Promise<void> {\n  return async (request, response) => {\n    try {\n      const identity = await options.getRateIdentity(request);\n\n      if (identity.kind !== \"authenticated\") {\n        throw new WechatImportError(\"AUTH_REQUIRED\");\n      }\n\n      if (!(options.isEnabled ?? isWechatImportEnabled)()) {\n        throw new WechatImportError(\"IMPORT_DISABLED\");\n      }\n\n      const url = request.body && typeof request.body === \"object\"\n        ? (request.body as { url?: unknown }).url\n        : undefined;\n\n      if (typeof url !== \"string\") {\n        throw new WechatImportError(\"INVALID_URL\");\n      }\n\n      // Only authenticated accounts can import; invalid URLs do not use quota.\n      const parsed = parseWechatArticleInput(url);\n\n      if (!parsed.ok) {\n        throw new WechatImportError(\"INVALID_URL\", parsed.message);\n      }\n\n      if (!options.limiter.consume(identity.key, identity.kind)) {\n        throw new WechatImportError(\"RATE_LIMITED\");\n      }\n\n      const result = await options.preview(parsed.url, request);\n      response.json(result);\n    } catch (error) {\n      if (error instanceof WechatImportError) {\n        response.status(error.status).json({\n          error: {\n            code: error.code,\n            message: error.message,\n          },\n        });\n        return;\n      }\n\n      console.error(\n        \"[wechat-import] unexpected failure\",\n        error instanceof Error ? error.name : \"unknown\",\n      );\n      const fallback = new WechatImportError(\"UPSTREAM_ERROR\");\n      response.status(fallback.status).json({\n        error: {\n          code: fallback.code,\n          message: fallback.message,\n        },\n      });\n    }\n  };\n}\n"
    },
    {
      "path": "src/App.tsx",
      "content": "import {\n  useEffect,\n  useLayoutEffect,\n  useMemo,\n  useRef,\n  useState,\n  type PointerEvent as ReactPointerEvent,\n} from \"react\";\nimport { CategorySidebar } from \"./components/CategorySidebar\";\nimport { AiReviewDialog } from \"./components/AiReviewDialog\";\nimport { ChangePasswordDialog } from \"./components/ChangePasswordDialog\";\nimport { ConfirmDialog } from \"./components/ConfirmDialog\";\nimport { EditorPanel, type EditorPanelHandle } from \"./components/EditorPanel\";\nimport { LoginDialog } from \"./components/LoginDialog\";\nimport { MoveNoteDialog } from \"./components/MoveNoteDialog\";\nimport { NoteSidebar } from \"./components/NoteSidebar\";\nimport { WechatImportDialog } from \"./components/WechatImportDialog\";\nimport { SitePublishPanel } from \"./features/site-publishing/SitePublishPanel\";\nimport { PreviewPanel } from \"./components/PreviewPanel\";\nimport { SettingsPanel } from \"./components/SettingsPanel\";\nimport { SharePanel } from \"./components/SharePanel\";\nimport {\n  getInitialAiEnabled,\n  getInitialFooterBrand,\n  getInitialFooterLogoUrl,\n  getInitialFooterVia,\n  getInitialNoteCardTheme,\n  getInitialNoteWorkspace,\n  getRenderMode,\n  isSmartisanWebTestDataMode,\n  NOTE_CARD_THEME_STORAGE_KEY,\n  persistAiEnabled,\n  persistFooterLogoUrl,\n  persistFooterText,\n  persistNoteWorkspace,\n  THEME_STORAGE_KEY,\n} from \"./lib/app-state\";\nimport { getAiStatus } from \"./lib/ai\";\nimport {\n  canUseCloudWorkspace,\n  changeUserPassword,\n  downloadHermesSkillPackage,\n  getHermesSkillInstallLink,\n  getAuthState,\n  getCloudWorkspace,\n  loginUser,\n  logoutUser,\n  resetHermesSkillInstallLink,\n  saveCloudWorkspace,\n  type AuthUser,\n} from \"./lib/auth\";\nimport { copyTextToClipboard, normalizeClipboardMarkdown } from \"./lib/clipboard\";\nimport {\n  exportMarkdownArchive,\n  exportMarkdownAsPng,\n  exportNoteWorkspaceArchive,\n  getExportErrorMessage,\n  type WorkspaceArchiveProgress,\n} from \"./lib/export\";\nimport { buildHermesSkillInstallInstruction } from \"./lib/hermes\";\nimport { splitSections } from \"./lib/markdown\";\nimport { useResolvedTheme } from \"./lib/use-theme\";\nimport {\n  getCategoryNoteDocuments,\n  getFolderIdFromCategory,\n  orderNoteDocuments,\n} from \"./lib/notes\";\nimport {\n  parseNoteRouteHash,\n  writeCurrentNoteRoute,\n  type NoteRoute,\n  type NoteRouteView,\n} from \"./lib/note-route\";\nimport {\n  createCloudSaveQueue,\n  handleWorkspaceSaveShortcut,\n  shouldApplyPolledWorkspace,\n  shouldMarkCloudSyncComplete,\n  type CloudSaveQueue,\n} from \"./lib/workspace-save\";\nimport {\n  decideCloudWorkspaceRefresh,\n  getCloudWorkspaceRefreshFailureMessage,\n  getCloudWorkspaceRefreshNotice,\n  resolveAnonymousWorkspaceRefresh,\n  type CloudWorkspaceRefreshRequest,\n} from \"./lib/workspace-refresh\";\nimport { getWechatConnectionStatus } from \"./lib/wechat-config\";\nimport {\n  copyMarkdownForWechat,\n  publishMarkdownAsWechatDraft,\n} from \"./lib/wechat\";\nimport { useAppStore } from \"./store/useAppStore\";\nimport type {\n  CopyState,\n  NoteCardThemeId,\n  NoteCategoryId,\n  NoteFolder,\n  NoteWorkspace,\n} from \"./types/app\";\n\ntype MobileWorkspaceView = \"notes\" | \"editor\" | \"preview\";\ntype DesktopWorkspaceView = \"editor\" | \"preview\";\ntype WechatCopyState = \"idle\" | \"preparing\" | \"copied\" | \"failed\";\ntype WechatDraftState = \"idle\" | \"publishing\" | \"published\" | \"failed\";\ntype HermesSkillLinkActionState =\n  | \"idle\"\n  | \"copying\"\n  | \"copied\"\n  | \"resetting\"\n  | \"reset\";\n\ninterface NoteRefreshFeedback {\n  tone: \"notice\" | \"error\";\n  message: string;\n}\n\ninterface NoteRouteNavigation {\n  revision: number;\n  route: NoteRoute | null;\n}\n\n// 刷新便签只重读当前工作区，不再重载页面；该值现在只保证旋转反馈被看见。\nconst NOTE_REFRESH_DELAY_MS = 650;\nconst CLOUD_SAVE_DELAY_MS = 650;\nconst CLOUD_POLL_INTERVAL_MS = 15_000;\nconst HERMES_SKILL_LINK_RESET_CONFIRMATION = {\n  title: \"重置 Hermes 安装链接？\",\n  description:\n    \"重置后，当前专属链接会立即失效，之后无法再用于下载；已经安装的 Skill 不受影响。\",\n  confirmLabel: \"确认重置\",\n};\n\nfunction getCurrentWorkspace(): NoteWorkspace {\n  const state = useAppStore.getState();\n\n  return {\n    activeNoteId: state.activeNoteId,\n    folders: state.folders,\n    notes: state.notes,\n    version: 1,\n  };\n}\n\n/**\n * Ctrl/Cmd+S 只有焦点在编辑器正文控件（或编辑器内的按钮/图片）时才真正保存；\n * 搜索框、文件夹下拉、图片预览/裁剪弹窗等不能把保存误发给当前文章。\n */\nfunction isSaveShortcutTargetAllowed(target: EventTarget | null): boolean {\n  if (!(target instanceof Element)) {\n    return true;\n  }\n\n  if (target.closest('[role=\"dialog\"]')) {\n    return false;\n  }\n\n  const control = target.closest(\n    'input, textarea, select, [contenteditable=\"true\"]',\n  );\n\n  if (!control) {\n    return true;\n  }\n\n  return Boolean(control.closest(\".editor-panel\"));\n}\n\nfunction getCategoryLabel(\n  categoryId: NoteCategoryId,\n  folders: NoteFolder[],\n): string {\n  if (categoryId === \"all\") {\n    return \"全部便签\";\n  }\n\n  if (categoryId === \"starred\") {\n    return \"加星便签\";\n  }\n\n  if (categoryId === \"trash\") {\n    return \"回收站\";\n  }\n\n  const folderId = getFolderIdFromCategory(categoryId);\n  return folders.find((folder) => folder.id === folderId)?.name ?? \"全部便签\";\n}\n\nfunction getCopyButtonText(copyState: CopyState): string {\n  if (copyState === \"copied\") {\n    return \"已复制文字\";\n  }\n\n  if (copyState === \"failed\") {\n    return \"复制失败\";\n  }\n\n  return \"复制文字\";\n}\n\nfunction getWechatCopyButtonText(copyState: WechatCopyState): string {\n  if (copyState === \"preparing\") {\n    return \"正在处理图片...\";\n  }\n\n  if (copyState === \"copied\") {\n    return \"已复制到公众号\";\n  }\n\n  if (copyState === \"failed\") {\n    return \"公众号复制失败\";\n  }\n\n  return \"复制到公众号\";\n}\n\nfunction getWechatDraftButtonText(state: WechatDraftState): string {\n  if (state === \"publishing\") {\n    return \"正在发布草稿...\";\n  }\n\n  if (state === \"published\") {\n    return \"已保存到公众号草稿\";\n  }\n\n  if (state === \"failed\") {\n    return \"草稿发布失败\";\n  }\n\n  return \"发布为公众号草稿\";\n}\n\nfunction formatMobileNoteUpdatedAt(timestamp: number | undefined): string {\n  if (!timestamp) {\n    return \"\";\n  }\n\n  return new Intl.DateTimeFormat(\"zh-CN\", {\n    month: \"numeric\",\n    day: \"numeric\",\n    hour: \"2-digit\",\n    minute: \"2-digit\",\n    hour12: false,\n  }).format(new Date(timestamp));\n}\n\nexport default function App() {\n  const renderMode = getRenderMode();\n  const isPlaywrightRender = renderMode === \"playwright\";\n  const isTestDataMode = isSmartisanWebTestDataMode();\n  const [footerBrand, setFooterBrand] = useState(getInitialFooterBrand);\n  const [footerLogoUrl, setFooterLogoUrl] = useState(getInitialFooterLogoUrl);\n  const [footerVia, setFooterVia] = useState(getInitialFooterVia);\n  const [aiEnabled, setAiEnabled] = useState(getInitialAiEnabled);\n  const [aiAvailable, setAiAvailable] = useState(false);\n  const [aiReviewNoteId, setAiReviewNoteId] = useState<string | null>(null);\n  const [isArchiving, setIsArchiving] = useState(false);\n  const [isWorkspaceArchiveExporting, setIsWorkspaceArchiveExporting] =\n    useState(false);\n  const [workspaceArchiveProgress, setWorkspaceArchiveProgress] =\n    useState<WorkspaceArchiveProgress | null>(null);\n  const [workspaceArchiveError, setWorkspaceArchiveError] = useState(\"\");\n  const [isImportingImage, setIsImportingImage] = useState(false);\n  const [isRefreshingNotes, setIsRefreshingNotes] = useState(false);\n  const [noteRefreshFeedback, setNoteRefreshFeedback] =\n    useState<NoteRefreshFeedback | null>(null);\n  const [isNoteSidebarOpen, setIsNoteSidebarOpen] = useState(false);\n  const [isCategorySidebarOpen, setIsCategorySidebarOpen] = useState(false);\n  const [isSettingsOpen, setIsSettingsOpen] = useState(false);\n  const [isShareOpen, setIsShareOpen] = useState(false);\n  const [isDesktopViewMenuOpen, setIsDesktopViewMenuOpen] = useState(false);\n  const [isMove