      "path": "src/lib/export.ts",
      "content": "import { EXPORT_RETRY_BASE_DELAY_MS, EXPORT_RETRY_LIMIT, EXPORT_REQUEST_TIMEOUT_MS } from \"./export-config.js\";\nimport type {\n  NoteCardThemeId,\n  NoteWorkspace,\n} from \"../types/app.js\";\nimport { ExportError } from \"../types/app.js\";\n\ninterface ExportErrorPayload {\n  error?: string;\n  hint?: string;\n}\n\ninterface ExportFooterOptions {\n  footerBrand: string;\n  footerLogoUrl: string;\n  footerVia: string;\n}\n\ninterface WorkspaceArchiveJobPayload {\n  id: string;\n  status: \"preparing\" | \"collecting\" | \"packaging\" | \"ready\" | \"failed\";\n  progress: number;\n  message: string;\n  completedNotes: number;\n  totalNotes: number;\n  error?: string;\n  filename?: string;\n}\n\nexport interface WorkspaceArchiveProgress {\n  percent: number;\n  message: string;\n  completedNotes: number;\n  totalNotes: number;\n}\n\nconst contentDispositionFilenamePattern = /filename\\*?=(?:UTF-8''|\")?([^\";]+)/i;\nconst workspaceArchivePollIntervalMs = 400;\nconst workspaceArchiveTimeoutMs = 30 * 60 * 1_000;\n\nfunction padDatePart(value: number): string {\n  return String(value).padStart(2, \"0\");\n}\n\nfunction buildExportFilename(): string {\n  const now = new Date();\n  const formatted = [\n    now.getFullYear(),\n    padDatePart(now.getMonth() + 1),\n    padDatePart(now.getDate()),\n    padDatePart(now.getHours()),\n    padDatePart(now.getMinutes()),\n    padDatePart(now.getSeconds()),\n  ].join(\"-\");\n\n  return `${formatted}-${Date.now()}.png`;\n}\n\nfunction wait(ms: number): Promise<void> {\n  return new Promise((resolve) => {\n    globalThis.setTimeout(resolve, ms);\n  });\n}\n\nfunction getFilenameFromContentDisposition(value: string | null, fallback: string): string {\n  if (!value) {\n    return fallback;\n  }\n\n  const match = contentDispositionFilenamePattern.exec(value);\n\n  if (!match) {\n    return fallback;\n  }\n\n  return decodeURIComponent(match[1].replace(/^\"|\"$/g, \"\"));\n}\n\nasync function saveBlob(blob: Blob, filename: string): Promise<void> {\n  const isCoarsePointer =\n    typeof window !== \"undefined\" &&\n    window.matchMedia?.(\"(pointer: coarse)\").matches;\n  const objectUrl = URL.createObjectURL(blob);\n\n  try {\n    const file = new File([blob], filename, { type: blob.type || \"application/octet-stream\" });\n\n    if (\n      isCoarsePointer &&\n      typeof navigator !== \"undefined\" &&\n      navigator.share &&\n      navigator.canShare?.({ files: [file] })\n    ) {\n      try {\n        await navigator.share({\n          files: [file],\n          title: filename,\n        });\n        return;\n      } catch (error) {\n        if (error instanceof Error && error.name === \"AbortError\") {\n          return;\n        }\n\n        console.warn(\"Share failed, falling back to download.\", error);\n      }\n    }\n\n    const link = document.createElement(\"a\");\n    link.href = objectUrl;\n    link.download = filename;\n    link.rel = \"noopener\";\n\n    if (isCoarsePointer) {\n      link.target = \"_blank\";\n      link.download = \"\";\n    }\n\n    document.body.append(link);\n    link.click();\n    link.remove();\n  } finally {\n    globalThis.setTimeout(() => {\n      URL.revokeObjectURL(objectUrl);\n    }, 60_000);\n  }\n}\n\nasync function readExportErrorMessage(response: Response): Promise<string> {\n  const contentType = response.headers.get(\"content-type\") || \"\";\n  const prefix = `导出服务返回 ${response.status}${response.statusText ? ` ${response.statusText}` : \"\"}`;\n\n  if (contentType.includes(\"application/json\")) {\n    const data = (await response.json().catch(() => null)) as ExportErrorPayload | null;\n    const parts = [data?.error, data?.hint].filter(\n      (part): part is string => Boolean(part),\n    );\n    return parts.length ? `${prefix}：${parts.join(\" \")}` : prefix;\n  }\n\n  const text = await response.text().catch(() => \"\");\n  const details = text.replace(/\\s+/g, \" \").trim().slice(0, 180);\n  return details ? `${prefix}：${details}` : prefix;\n}\n\nfunction normalizeExportError(error: unknown, attempt: number): ExportError {\n  if (error instanceof DOMException && error.name === \"AbortError\") {\n    return new ExportError(`导出请求超时（>${EXPORT_REQUEST_TIMEOUT_MS / 1000}s）`, {\n      retriable: true,\n      attempts: attempt,\n    });\n  }\n\n  if (error instanceof TypeError) {\n    return new ExportError(`导出请求未送达后端：${error.message}`, {\n      retriable: true,\n      attempts: attempt,\n    });\n  }\n\n  if (error instanceof ExportError) {\n    error.attempts = attempt;\n    return error;\n  }\n\n  if (error instanceof Error) {\n    return new ExportError(error.message, {\n      attempts: attempt,\n    });\n  }\n\n  return new ExportError(\"导出失败，原因未知\", {\n    attempts: attempt,\n  });\n}\n\nfunction shouldRetryExport(error: unknown): error is ExportError {\n  return error instanceof ExportError && error.retriable;\n}\n\nasync function tryServerExport(\n  markdown: string,\n  filename: string,\n  theme: NoteCardThemeId,\n  footer: ExportFooterOptions,\n): Promise<Blob> {\n  const maxAttempts = EXPORT_RETRY_LIMIT + 1;\n\n  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {\n    const controller = new AbortController();\n    const timeoutId = globalThis.setTimeout(() => {\n      controller.abort();\n    }, EXPORT_REQUEST_TIMEOUT_MS);\n\n    try {\n      const response = await fetch(\"/api/export\", {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n        },\n        body: JSON.stringify({\n          filename,\n          footerBrand: footer.footerBrand,\n          footerLogoUrl: footer.footerLogoUrl,\n          footerVia: footer.footerVia,\n          markdown,\n          theme,\n        }),\n        signal: controller.signal,\n      });\n\n      if (!response.ok) {\n        throw new ExportError(await readExportErrorMessage(response), {\n          status: response.status,\n          retriable: response.status >= 500 || response.status === 429,\n          attempts: attempt,\n        });\n      }\n\n      const renderedTheme = response.headers.get(\"X-Export-Theme\");\n\n      if (renderedTheme !== theme) {\n        throw new ExportError(\n          \"导出服务尚未更新到当前主题版本，请重启后端服务后再保存图片。\",\n          {\n            status: 409,\n            retriable: false,\n            attempts: attempt,\n          },\n        );\n      }\n\n      return response.blob();\n    } catch (error) {\n      const normalizedError = normalizeExportError(error, attempt);\n\n      if (attempt >= maxAttempts || !shouldRetryExport(normalizedError)) {\n        throw normalizedError;\n      }\n\n      await wait(EXPORT_RETRY_BASE_DELAY_MS * attempt);\n    } finally {\n      globalThis.clearTimeout(timeoutId);\n    }\n  }\n\n  throw new ExportError(\"导出失败，已超过最大重试次数\", {\n    attempts: maxAttempts,\n  });\n}\n\nexport async function exportMarkdownAsPng(\n  markdown: string,\n  theme: NoteCardThemeId,\n  footer: ExportFooterOptions,\n): Promise<void> {\n  const filename = buildExportFilename();\n  const blob = await tryServerExport(markdown, filename, theme, footer);\n  await saveBlob(blob, filename);\n}\n\nexport async function exportMarkdownArchive(\n  markdown: string,\n  theme: NoteCardThemeId,\n  footer: ExportFooterOptions,\n): Promise<void> {\n  const response = await fetch(\"/api/archive\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({\n      footerBrand: footer.footerBrand,\n      footerLogoUrl: footer.footerLogoUrl,\n      footerVia: footer.footerVia,\n      markdown,\n      theme,\n    }),\n  });\n\n  if (!response.ok) {\n    throw new ExportError(await readExportErrorMessage(response), {\n      status: response.status,\n      retriable: false,\n    });\n  }\n\n  if (response.headers.get(\"X-Archive-Theme\") !== theme) {\n    throw new ExportError(\n      \"归档服务尚未更新到当前主题版本，请重启后端服务后再下载。\",\n      {\n        status: 409,\n        retriable: false,\n      },\n    );\n  }\n\n  const filename = getFilenameFromContentDisposition(\n    response.headers.get(\"content-disposition\"),\n    \"notes-archive.zip\",\n  );\n  await saveBlob(await response.blob(), filename);\n}\n\nasync function downloadWorkspaceArchive(\n  job: WorkspaceArchiveJobPayload,\n  onProgress: (progress: WorkspaceArchiveProgress) => void,\n): Promise<void> {\n  const response = await fetch(`/api/workspace/archive/${job.id}/download`, {\n    cache: \"no-store\",\n  });\n\n  if (!response.ok) {\n    throw new ExportError(await readExportErrorMessage(response), {\n      status: response.status,\n      retriable: false,\n    });\n  }\n\n  const filename = getFilenameFromContentDisposition(\n    response.headers.get(\"content-disposition\"),\n    job.filename || \"smartisan-notes.zip\",\n  );\n  const contentLength = Number(response.headers.get(\"content-length\") || \"0\");\n\n  if (!response.body) {\n    onProgress({\n      percent: 98,\n      message: \"正在下载压缩包\",\n      completedNotes: job.totalNotes,\n      totalNotes: job.totalNotes,\n    });\n    await saveBlob(await response.blob(), filename);\n  } else {\n    const reader = response.body.getReader();\n    const chunks: ArrayBuffer[] = [];\n    let receivedBytes = 0;\n\n    while (true) {\n      const { done, value } = await reader.read();\n\n      if (done) {\n        break;\n      }\n\n      const chunk = new Uint8Array(value.byteLength);\n      chunk.set(value);\n      chunks.push(chunk.buffer);\n      receivedBytes += value.byteLength;\n      const downloadPercent = contentLength > 0\n        ? Math.min(99, 95 + Math.floor((receivedBytes / contentLength) * 4))\n        : 97;\n      onProgress({\n        percent: downloadPercent,\n        message: \"正在下载压缩包\",\n        completedNotes: job.totalNotes,\n        totalNotes: job.totalNotes,\n      });\n    }\n\n    await saveBlob(\n      new Blob(chunks, {\n        type: response.headers.get(\"content-type\") || \"application/zip\",\n      }),\n      filename,\n    );\n  }\n\n  onProgress({\n    percent: 100,\n    message: \"全部便签已导出\",\n    completedNotes: job.totalNotes,\n    totalNotes: job.totalNotes,\n  });\n}\n\nexport async function exportNoteWorkspaceArchive(\n  workspace: NoteWorkspace,\n  onProgress: (progress: WorkspaceArchiveProgress) => void,\n): Promise<void> {\n  const createResponse = await fetch(\"/api/workspace/archive\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify({ workspace }),\n  });\n\n  if (!createResponse.ok) {\n    throw new ExportError(await readExportErrorMessage(createResponse), {\n      status: createResponse.status,\n      retriable: false,\n    });\n  }\n\n  let job = (await createResponse.json()) as WorkspaceArchiveJobPayload;\n  const deadline = Date.now() + workspaceArchiveTimeoutMs;\n\n  onProgress({\n    percent: job.progress,\n    message: job.message,\n    completedNotes: job.completedNotes,\n    totalNotes: job.totalNotes,\n  });\n\n  while (job.status !== \"ready\") {\n    if (job.status === \"failed\") {\n      throw new ExportError(job.error || job.message || \"整体导出失败。\", {\n        retriable: false,\n      });\n    }\n\n    if (Date.now() >= deadline) {\n      throw new ExportError(\"整体导出等待超时，请稍后重试。\", {\n        retriable: false,\n      });\n    }\n\n    await wait(workspaceArchivePollIntervalMs);\n    const statusResponse = await fetch(`/api/workspace/archive/${job.id}`, {\n      cache: \"no-store\",\n    });\n\n    if (!statusResponse.ok) {\n      throw new ExportError(await readExportErrorMessage(statusResponse), {\n        status: statusResponse.status,\n        retriable: false,\n      });\n    }\n\n    job = (await statusResponse.json()) as WorkspaceArchiveJobPayload;\n    onProgress({\n      percent: job.progress,\n      message: job.message,\n      completedNotes: job.completedNotes,\n      totalNotes: job.totalNotes,\n    });\n  }\n\n  await downloadWorkspaceArchive(job, onProgress);\n}\n\nexport function getExportErrorMessage(error: unknown): string {\n  if (!(error instanceof Error)) {\n    return \"导出依赖后端 Playwright 服务，当前 /api/export 不可用。\";\n  }\n\n  const attempts =\n    error instanceof ExportError ? error.attempts : 1;\n  const retryCount = Math.max(attempts - 1, 0);\n  const retryLabel = retryCount > 0 ? `已自动重试 ${retryCount} 次。` : \"\";\n  return `${retryLabel}${error.message}`;\n}\n"
    },
    {
      "path": "src/lib/workspace-save.ts",
      "content": "import type { NoteWorkspace } from \"../types/app.js\";\n\n/**\n * 手动保存快捷键（Ctrl+S / Cmd+S）的最小事件形状，便于在单元测试里\n * 用普通对象直接验证行为，而不依赖真实 DOM。\n */\nexport interface SaveShortcutEventLike {\n  key: string;\n  ctrlKey: boolean;\n  metaKey: boolean;\n  altKey: boolean;\n  shiftKey: boolean;\n  repeat?: boolean;\n  isComposing?: boolean;\n}\n\n/**\n * 只判断是否命中 Ctrl/Cmd+S（大小写不敏感，排除 Alt/Shift 组合）。\n * 不在这里排除 repeat 或输入法组合态：编辑态一旦命中就必须先阻止浏览器\n * “保存网页”，再决定是否真正执行保存。\n */\nexport function matchesSaveShortcut(event: SaveShortcutEventLike): boolean {\n  if (!event.ctrlKey && !event.metaKey) {\n    return false;\n  }\n\n  if (event.altKey || event.shiftKey) {\n    return false;\n  }\n\n  return event.key.toLowerCase() === \"s\";\n}\n\n/** repeat 与输入法组合态允许拦截浏览器默认行为，但不能真正执行保存。 */\nexport function canExecuteSaveShortcut(event: SaveShortcutEventLike): boolean {\n  return !event.repeat && !event.isComposing;\n}\n\nexport interface CloudWorkspaceSaveResult {\n  updatedAt: number | null;\n  workspace: NoteWorkspace | null;\n}\n\nexport interface CloudSaveQueueOptions {\n  save: (workspace: NoteWorkspace) => Promise<CloudWorkspaceSaveResult>;\n  onSaved?: (result: CloudWorkspaceSaveResult) => void;\n  onError?: (error: unknown) => void;\n}\n\nexport interface CloudSaveQueue {\n  isSaving: () => boolean;\n  /** 是否有比当前在途请求更新的快照已排队等待写入。 */\n  hasPending: () => boolean;\n  /**\n   * 请求保存一份快照。同一时刻只允许一个 PUT 在途，在途期间再次调用会\n   * 合并为最新的那一份，保证旧快照不会晚于新快照写入服务端。\n   */\n  enqueue: (workspace: NoteWorkspace) => void;\n  /** 等待队列空闲，仅测试与收尾使用。 */\n  whenIdle: () => Promise<void>;\n}\n\n/**\n * 串行化云端工作区保存。除了保证写入顺序，`isSaving()` 也让轮询可以\n * 在本地保存未落地时直接跳过，避免把旧的云端数据回灌到编辑器。\n */\nexport function createCloudSaveQueue(\n  options: CloudSaveQueueOptions,\n): CloudSaveQueue {\n  let pending: NoteWorkspace | null = null;\n  let running = false;\n  let idleResolvers: Array<() => void> = [];\n\n  async function drain(): Promise<void> {\n    if (running) {\n      return;\n    }\n\n    running = true;\n\n    try {\n      while (pending !== null) {\n        const workspace = pending;\n        pending = null;\n\n        try {\n          const result = await options.save(workspace);\n          options.onSaved?.(result);\n        } catch (error) {\n          options.onError?.(error);\n        }\n      }\n    } finally {\n      running = false;\n\n      const resolvers = idleResolvers;\n      idleResolvers = [];\n      for (const resolve of resolvers) {\n        resolve();\n      }\n    }\n  }\n\n  return {\n    hasPending: () => pending !== null,\n    isSaving: () => running,\n    enqueue: (workspace) => {\n      pending = workspace;\n      void drain();\n    },\n    whenIdle: () => {\n      if (!running && pending === null) {\n        return Promise.resolve();\n      }\n\n      return new Promise<void>((resolve) => {\n        idleResolvers.push(resolve);\n      });\n    },\n  };\n}\n\nexport interface CloudSyncCompletionDecision {\n  hasPendingSave: boolean;\n  isDebounceScheduled: boolean;\n}\n\n/**\n * 只有队列没有更新的待保存快照、且没有新的防抖定时器时，才把状态显示为\n * “已同步”。前一个在途请求完成时，后续未保存的快照仍应保持“同步中”。\n */\nexport function shouldMarkCloudSyncComplete(\n  decision: CloudSyncCompletionDecision,\n): boolean {\n  return !decision.hasPendingSave && !decision.isDebounceScheduled;\n}\n\nexport interface PolledWorkspaceDecision {\n  polledUpdatedAt: number | null | undefined;\n  knownRevision: number;\n  hasPendingLocalSave: boolean;\n}\n\n/**\n * 轮询是否可以覆盖本地工作区。只要有本地保存待处理（debounce 未触发或\n * PUT 在途），就绝不覆盖，避免刚输入的内容被上一次云端快照回灌。\n */\nexport function shouldApplyPolledWorkspace(\n  decision: PolledWorkspaceDecision,\n): boolean {\n  if (decision.hasPendingLocalSave) {\n    return false;\n  }\n\n  return (\n    typeof decision.polledUpdatedAt === \"number\" &&\n    decision.polledUpdatedAt > decision.knownRevision\n  );\n}\n\nexport interface ManualWorkspaceSaveOptions {\n  isLoggedIn: boolean;\n  isCloudHydrated: boolean;\n  getLatestWorkspace: () => NoteWorkspace;\n  persistLocalWorkspace: (workspace: NoteWorkspace) => void;\n  clearPendingCloudSave: () => void;\n  enqueueCloudSave: (workspace: NoteWorkspace) => void;\n  markCloudSyncing?: () => void;\n}\n\nexport type ManualWorkspaceSaveOutcome =\n  | \"anonymous-persisted\"\n  | \"cloud-enqueued\"\n  | \"skipped-before-hydration\";\n\n/**\n * 实际写入流程：\n * - 匿名：立即写入 localStorage，绝不触碰云端。\n * - 已登录且已完成水合：清除 debounce 定时器后立即提交最新 store 快照。\n * - 会话加载/水合完成前：直接跳过，避免用本地旧数据覆盖云端。\n */\nexport function performManualWorkspaceSave(\n  options: ManualWorkspaceSaveOptions,\n): ManualWorkspaceSaveOutcome {\n  if (!options.isLoggedIn) {\n    options.persistLocalWorkspace(options.getLatestWorkspace());\n    return \"anonymous-persisted\";\n  }\n\n  if (!options.isCloudHydrated) {\n    return \"skipped-before-hydration\";\n  }\n\n  options.clearPendingCloudSave();\n  options.markCloudSyncing?.();\n  options.enqueueCloudSave(options.getLatestWorkspace());\n  return \"cloud-enqueued\";\n}\n\nexport interface SaveShortcutHandlingEvent extends SaveShortcutEventLike {\n  preventDefault: () => void;\n}\n\nexport interface WorkspaceSaveShortcutContext {\n  /** 是否处于编辑器工作区（非回收站、无覆盖层、桌面或手机编辑态）。 */\n  isEditorActive: boolean;\n  /** 焦点是否位于允许触发保存的编辑器控件内，而不是搜索框或内部弹窗。 */\n  isTargetAllowed: boolean;\n  /** 会话与当前便签是否已就绪；未就绪只拦截浏览器保存，不写入。 */\n  isWriteReady: boolean;\n  isLoggedIn: boolean;\n  isCloudHydrated: boolean;\n  getLatestWorkspace: () => NoteWorkspace;\n  persistLocalWorkspace: (workspace: NoteWorkspace) => void;\n  clearPendingCloudSave: () => void;\n  enqueueCloudSave: (workspace: NoteWorkspace) => void;\n  markCloudSyncing?: () => void;\n}\n\nexport type WorkspaceSaveShortcutOutcome =\n  | \"ignored\"\n  | \"prevented-only\"\n  | ManualWorkspaceSaveOutcome;\n\n/**\n * 编辑器保存快捷键的完整处理顺序，匹配与执行严格分离：\n * 1. 未命中 Ctrl/Cmd+S、不在编辑态或焦点在其他控件/弹窗：不拦截。\n * 2. 编辑器一旦命中：始终 `preventDefault()`，阻止浏览器“保存网页”。\n * 3. repeat、输入法组合态、会话未就绪：只拦截不写入。\n * 4. 其余情况按匿名/登录路径写入最新快照。\n */\nexport function handleWorkspaceSaveShortcut(\n  event: SaveShortcutHandlingEvent,\n  context: WorkspaceSaveShortcutContext,\n): WorkspaceSaveShortcutOutcome {\n  if (!matchesSaveShortcut(event)) {\n    return \"ignored\";\n  }\n\n  if (!context.isEditorActive || !context.isTargetAllowed) {\n    return \"ignored\";\n  }\n\n  event.preventDefault();\n\n  if (!context.isWriteReady) {\n    return \"prevented-only\";\n  }\n\n  if (!canExecuteSaveShortcut(event)) {\n    return \"prevented-only\";\n  }\n\n  return performManualWorkspaceSave({\n    isLoggedIn: context.isLoggedIn,\n    isCloudHydrated: context.isCloudHydrated,\n    getLatestWorkspace: context.getLatestWorkspace,\n    persistLocalWorkspace: context.persistLocalWorkspace,\n    clearPendingCloudSave: context.clearPendingCloudSave,\n    enqueueCloudSave: context.enqueueCloudSave,\n    markCloudSyncing: context.markCloudSyncing,\n  });\n}\n"
    },
    {
      "path": "src/store/useAppStore.ts",
      "content": "import { create } from \"zustand\";\nimport { getInitialNoteWorkspace, getInitialTheme } from \"../lib/app-state\";\nimport {\n  createNoteFolder,\n  createNoteDocument,\n  discardEmptyNoteDraft,\n  getNoteDocumentById,\n  moveNoteToFolder,\n  moveNoteToTrash,\n  reorderNormalNoteDocuments,\n  resolveWorkspaceActiveNote,\n  restoreNoteFromTrash,\n  toggleNotePinned,\n  toggleNoteStarred,\n} from \"../lib/notes\";\nimport type {\n  CopyState,\n  NoteDocument,\n  NoteFolder,\n  NoteWorkspace,\n  PendingAction,\n  ThemePreferenceId,\n} from \"../types/app\";\n\ninterface AppStoreState {\n  activeNoteId: string;\n  folders: NoteFolder[];\n  notes: NoteDocument[];\n  markdown: string;\n  selectedTheme: ThemePreferenceId;\n  isExporting: boolean;\n  exportError: string;\n  copyState: CopyState;\n  pendingAction: PendingAction | null;\n  createNote: (\n    markdown?: string,\n    folderId?: string | null,\n    isStarred?: boolean,\n  ) => string;\n  discardEmptyDraft: (noteId: string, preferredNextNoteId?: string) => void;\n  createFolder: (name: string) => string | null;\n  deleteFolder: (folderId: string) => void;\n  selectNote: (noteId: string) => void;\n  requestDeleteNote: (noteId: string) => void;\n  requestPermanentlyDeleteNote: (noteId: string) => void;\n  replaceWorkspace: (\n    workspace: NoteWorkspace,\n    options?: { preserveActiveNote?: boolean },\n  ) => void;\n  restoreNote: (noteId: string) => void;\n  reorderNotes: (activeNoteId: string, overNoteId: string) => void;\n  moveNoteToFolder: (noteId: string, folderId: string | null) => void;\n  setMarkdown: (markdown: string) => void;\n  setSelectedTheme: (theme: ThemePreferenceId) => void;\n  setIsExporting: (isExporting: boolean) => void;\n  setExportError: (exportError: string) => void;\n  setCopyState: (copyState: CopyState) => void;\n  togglePinned: (noteId: string) => void;\n  toggleStarred: (noteId: string) => void;\n  requestReplaceMarkdown: (\n    nextMarkdown: string,\n    title: string,\n    description: string,\n  ) => void;\n  clearPendingAction: () => void;\n  confirmPendingAction: () => void;\n}\n\nconst initialWorkspace = getInitialNoteWorkspace();\nconst initialActiveNote =\n  initialWorkspace.notes.find((note) => note.id === initialWorkspace.activeNoteId) ??\n  initialWorkspace.notes[0];\n\nexport const useAppStore = create<AppStoreState>((set, get) => ({\n  activeNoteId: initialActiveNote.id,\n  folders: initialWorkspace.folders,\n  notes: initialWorkspace.notes,\n  markdown: initialActiveNote.markdown,\n  selectedTheme: getInitialTheme(),\n  isExporting: false,\n  exportError: \"\",\n  copyState: \"idle\",\n  pendingAction: null,\n  createNote: (markdown = \"\", folderId = null, isStarred = false) => {\n    let createdNoteId = \"\";\n\n    set((state) => {\n      const firstNormalOrder = state.notes.reduce(\n        (smallest, note) => Math.min(smallest, note.normalOrder),\n        0,\n      );\n      const note = createNoteDocument(\n        markdown,\n        Date.now(),\n        firstNormalOrder - 1,\n        folderId,\n        isStarred,\n      );\n      createdNoteId = note.id;\n\n      return {\n        activeNoteId: note.id,\n        exportError: \"\",\n        markdown: note.markdown,\n        notes: [note, ...state.notes],\n        pendingAction: null,\n      };\n    });\n\n    return createdNoteId;\n  },\n  discardEmptyDraft: (noteId, preferredNextNoteId) =>\n    set((state) => {\n      const discarded = discardEmptyNoteDraft(\n        state.notes,\n        noteId,\n        preferredNextNoteId,\n      );\n\n      if (!discarded) {\n        return {};\n      }\n\n      if (state.activeNoteId !== noteId) {\n        return {\n          notes: discarded.notes,\n        };\n      }\n\n      return {\n        activeNoteId: discarded.activeNote.id,\n        exportError: \"\",\n        markdown: discarded.activeNote.markdown,\n        notes: discarded.notes,\n        pendingAction: null,\n      };\n    }),\n  createFolder: (name) => {\n    const normalizedName = name.trim();\n\n    if (!normalizedName) {\n      return null;\n    }\n\n    const existingFolder = get().folders.find(\n      (folder) => folder.name.toLocaleLowerCase() === normalizedName.toLocaleLowerCase(),\n    );\n\n    if (existingFolder) {\n      return existingFolder.id;\n    }\n\n    const folder = createNoteFolder(normalizedName);\n    set((state) => ({\n      folders: [...state.folders, folder],\n    }));\n    return folder.id;\n  },\n  deleteFolder: (folderId) =>\n    set((state) => ({\n      folders: state.folders.filter((folder) => folder.id !== folderId),\n      notes: state.notes.map((note) =>\n        note.folderId === folderId\n          ? {\n              ...note,\n              folderId: null,\n            }\n          : note,\n      ),\n    })),\n  selectNote: (noteId) => {\n    const note = getNoteDocumentById(get().notes, noteId);\n\n    if (!note) {\n      return;\n    }\n\n    set({\n      activeNoteId: note.id,\n      exportError: \"\",\n      markdown: note.markdown,\n      pendingAction: null,\n    });\n  },\n  requestDeleteNote: (noteId) => {\n    const note = get().notes.find((candidate) => candidate.id === noteId);\n\n    if (!note) {\n      return;\n    }\n\n    set({\n      pendingAction: {\n        kind: \"delete-note\",\n        noteId,\n        title: \"将这张便签移到回收站？\",\n        description: \"便签会保留在回收站中，你之后仍可恢复或永久删除。\",\n        confirmLabel: \"移到回收站\",\n      },\n    });\n  },\n  requestPermanentlyDeleteNote: (noteId) => {\n    const note = get().notes.find((candidate) => candidate.id === noteId);\n\n    if (!note || note.deletedAt === null) {\n      return;\n    }\n\n    set({\n      pendingAction: {\n        kind: \"permanently-delete-note\",\n        noteId,\n        title: \"永久删除这张便签？\",\n        description: \"永久删除后无法恢复，便签中的 Markdown 内容也会一并移除。\",\n        confirmLabel: \"永久删除\",\n      },\n    });\n  },\n  replaceWorkspace: (workspace, options) =>\n    set((state) => {\n      const activeNote = resolveWorkspaceActiveNote(\n        workspace,\n        options?.preserveActiveNote ? state.activeNoteId : undefined,\n      );\n\n      if (!activeNote) {\n        return {};\n      }\n\n      return {\n        activeNoteId: activeNote.id,\n        exportError: \"\",\n        folders: workspace.folders,\n        markdown: activeNote.markdown,\n        notes: workspace.notes,\n        pendingAction: null,\n      };\n    }),\n  restoreNote: (noteId) =>\n    set((state) => ({\n      notes: restoreNoteFromTrash(state.notes, noteId),\n    })),\n  reorderNotes: (activeNoteId, overNoteId) =>\n    set((state) => ({\n      notes: reorderNormalNoteDocuments(\n        state.notes,\n        activeNoteId,\n        overNoteId,\n      ),\n    })),\n  moveNoteToFolder: (noteId, folderId) =>\n    set((state) => {\n      const isKnownFolder =\n        folderId === null || state.folders.some((folder) => folder.id === folderId);\n\n      return isKnownFolder\n        ? {\n            notes: moveNoteToFolder(state.notes, noteId, folderId),\n          }\n        : {};\n    }),\n  setMarkdown: (markdown) =>\n    set((state) => {\n      const updatedAt = Date.now();\n      return {\n        markdown,\n        notes: state.notes.map((note) =>\n          note.id === state.activeNoteId\n            ? {\n                ...note,\n                markdown,\n                updatedAt,\n              }\n            : note,\n        ),\n      };\n    }),\n  setSelectedTheme: (selectedTheme) => set({ selectedTheme }),\n  setIsExporting: (isExporting) => set({ isExporting }),\n  setExportError: (exportError) => set({ exportError }),\n  setCopyState: (copyState) => set({ copyState }),\n  togglePinned: (noteId) =>\n    set((state) => ({\n      notes: toggleNotePinned(state.notes, noteId),\n    })),\n  toggleStarred: (noteId) =>\n    set((state) => ({\n      notes: toggleNoteStarred(state.notes, noteId),\n    })),\n  requestReplaceMarkdown: (nextMarkdown, title, description) =>\n    set((state) => ({\n      pendingAction: {\n        kind: \"replace-markdown\",\n        noteId: state.activeNoteId,\n        nextMarkdown,\n        title,\n        description,\n        confirmLabel: \"确认覆盖\",\n      },\n    })),\n  clearPendingAction: () => set({ pendingAction: null }),\n  confirmPendingAction: () => {\n    const { activeNoteId, notes, pendingAction } = get();\n\n    if (!pendingAction) {\n      return;\n    }\n\n    if (pendingAction.kind === \"replace-markdown\") {\n      const updatedAt = Date.now();\n      set({\n        markdown:\n          pendingAction.noteId === activeNoteId\n            ? pendingAction.nextMarkdown\n            : get().markdown,\n        notes: notes.map((note) =>\n          note.id === pendingAction.noteId\n            ? {\n                ...note,\n                markdown: pendingAction.nextMarkdown,\n                updatedAt,\n              }\n            : note,\n        ),\n        pendingAction: null,\n      });\n      return;\n    }\n\n    if (pendingAction.kind === \"delete-note\") {\n      const deletedNotes = moveNoteToTrash(notes, pendingAction.noteId);\n\n      if (pendingAction.noteId !== activeNoteId) {\n        set({\n          notes: deletedNotes,\n          pendingAction: null,\n        });\n        return;\n      }\n\n      const liveNotes = deletedNotes.filter((note) => note.deletedAt === null);\n\n      if (liveNotes.length === 0) {\n        const emptyNote = createNoteDocument();\n        set({\n          activeNoteId: emptyNote.id,\n          exportError: \"\",\n          markdown: emptyNote.markdown,\n          notes: [emptyNote, ...deletedNotes],\n          pendingAction: null,\n        });\n        return;\n      }\n\n      const nextActiveNote = liveNotes[0];\n      set({\n        activeNoteId: nextActiveNote.id,\n        exportError: \"\",\n        markdown: nextActiveNote.markdown,\n        notes: deletedNotes,\n        pendingAction: null,\n      });\n      return;\n    }\n\n    const noteIndex = notes.findIndex((note) => note.id === pendingAction.noteId);\n    const remainingNotes = notes.filter((note) => note.id !== pendingAction.noteId);\n\n    if (remainingNotes.length === 0) {\n      const emptyNote = createNoteDocument();\n      set({\n        activeNoteId: emptyNote.id,\n        exportError: \"\",\n        markdown: emptyNote.markdown,\n        notes: [emptyNote],\n        pendingAction: null,\n      });\n      return;\n    }\n\n    if (pendingAction.noteId !== activeNoteId) {\n      set({\n        notes: remainingNotes,\n        pendingAction: null,\n      });\n      return;\n    }\n\n    const nextActiveNote =\n      remainingNotes.find((note) => note.deletedAt === null) ??\n      remainingNotes[Math.min(Math.max(noteIndex, 0), remainingNotes.length - 1)];\n    set({\n      activeNoteId: nextActiveNote.id,\n      exportError: \"\",\n      markdown: nextActiveNote.markdown,\n      notes: remainingNotes,\n      pendingAction: null,\n    });\n  },\n}));\n"
    }
  ],
